package com.bentleyplayz.stardewmodmanager;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.net.Uri;
import android.provider.DocumentsContract;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import androidx.documentfile.provider.DocumentFile;
import org.json.JSONObject;
import org.w3c.dom.*;
import javax.xml.parsers.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.zip.*;

public class MainActivity extends Activity {
  private static final int PICK_ROOT=10, PICK_ZIP=12, PICK_LOG=13, PICK_SAVE=14;
  private Uri rootUri, saveUri;
  private Document saveDoc;
  private LinearLayout content;
  private TextView status, modsList;
  private final int BG=0xFF10131C, PANEL=0xFF1B2130, ACCENT=0xFF9B8CFF, TEXT=0xFFF3F4FA, MUTED=0xFFABB2C5;
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);rootUri=readUri("root_uri");buildUi();}
  private Uri readUri(String k){String s=getPreferences(0).getString(k,null);return s==null?null:Uri.parse(s);}
  private void storeUri(String k,Uri u){getPreferences(0).edit().putString(k,u.toString()).apply();}
  private void buildUi(){
    ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(24),dp(20),dp(32));scroll.addView(content);setContentView(scroll);
    content.addView(txt("BENTLEY PLAYZ",12,ACCENT,true));TextView title=txt("Stardew Mod Manager",27,TEXT,true);title.setPadding(0,dp(5),0,dp(4));content.addView(title);content.addView(txt("MODS  •  SAVES  •  SMAPI TOOLS",11,MUTED,true));
    status=txt("Grant access to the SMAPI game folder to get started.",13,MUTED,false);status.setPadding(0,dp(16),0,dp(12));content.addView(status);
    section("STORAGE ACCESS");button("Grant SMAPI game-folder access",()->pickTree(PICK_ROOT));panel(txt("Select the exact Android/data/abc.smapi.gameloader/files folder. The app will test read/write access, then use Mods, Saves, ErrorLogs, Stardew Assets, and save-backups beneath it.",12,MUTED,false));
    section("MOD MANAGER");button("Import mod ZIP",()->pickDocument(PICK_ZIP,"application/zip"));button("Refresh installed mods",()->showMods());modsList=txt("No mod list loaded yet.",13,MUTED,false);panel(modsList);
    section("SMAPI LOG ANALYZER");button("Import and analyze SMAPI log",()->pickDocument(PICK_LOG,"*/*"));
    section("SAVE MANAGER");button("Open Stardew save file",()->pickDocument(PICK_SAVE,"*/*"));button("Edit character and core stats",()->editSave());button("Create save backup now",()->backupSave());button("Restore a backup",()->restoreBackup());
    section("ABOUT STORAGE");panel(txt("The requested folder is Android/data/abc.smapi.gameloader/files. A successful tree grant covers its descendants. The app verifies read and write access with a temporary test file and removes it. If DocumentsUI refuses the folder, the app reports the failure instead of pretending it has access.",12,MUTED,false));
    if(rootUri!=null)status.setText("Saved SMAPI game-folder permission found. Refresh installed mods to check access.");
  }
  private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}
  private TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
  private void section(String s){TextView t=txt(s,11,ACCENT,true);t.setPadding(0,dp(22),0,dp(9));content.addView(t);}
  private void panel(View v){LinearLayout box=new LinearLayout(this);box.setPadding(dp(14),dp(13),dp(14),dp(13));box.setBackgroundColor(PANEL);box.setOrientation(1);box.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);content.addView(box,p);}
  private void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setTextSize(14);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PANEL));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);content.addView(b,p);}
  private void pickTree(int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,Uri.parse("content://com.android.externalstorage.documents/tree/primary%3AAndroid%2Fdata%2Fabc.smapi.gameloader%2Ffiles"));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,req);}
  private void pickDocument(int req,String type){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,req);}
  @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}
    if(req==PICK_ROOT){DocumentFile selected=DocumentFile.fromTreeUri(this,u);if(selected==null||!selected.isDirectory()||!"files".equalsIgnoreCase(selected.getName())){status.setText("Select the exact SMAPI files folder: Android/data/abc.smapi.gameloader/files. If DocumentsUI blocks it, this Android version does not grant access.");return;}try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(u,flags);if((flags&Intent.FLAG_GRANT_READ_URI_PERMISSION)==0||(flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new IOException("The picker did not return both read and write permission.");selected.listFiles();DocumentFile probe=selected.createFile("text/plain",".bentley_permission_test");if(probe==null)throw new IOException("Folder is readable but write access was not granted.");try(OutputStream out=getContentResolver().openOutputStream(probe.getUri())){out.write("permission test".getBytes("UTF-8"));}if(!probe.delete())throw new IOException("Permission test file could not be removed.");rootUri=u;storeUri("root_uri",u);status.setText("SMAPI files-folder permission saved and read/write access verified.");showMods();}catch(Exception e){status.setText("Folder grant test failed: "+e.getMessage());}}
    if(req==PICK_ZIP)installZip(u);if(req==PICK_LOG)analyzeLog(u);if(req==PICK_SAVE){saveUri=u;loadSave();}
  }
  private DocumentFile appFilesDirectory(){if(rootUri==null)return null;return DocumentFile.fromTreeUri(this,rootUri);}
  private DocumentFile modsDirectory(){DocumentFile files=appFilesDirectory();return files==null?null:files.findFile("Mods");}
  private void showMods(){if(rootUri==null){status.setText("Grant SMAPI game-folder access first.");return;}try{DocumentFile d=modsDirectory();if(d==null||!d.isDirectory()){status.setText("No Mods folder found at abc.smapi.gameloader/files/Mods. Check that the SMAPI folder grant is correct.");modsList.setText("Mods folder not found.");return;}StringBuilder out=new StringBuilder();int count=0;if(d!=null&&d.isDirectory())for(DocumentFile f:d.listFiles())if(f.isDirectory()){DocumentFile mf=f.findFile("manifest.json");String name=f.getName(),version="manifest missing",id="";if(mf!=null){try(InputStream in=getContentResolver().openInputStream(mf.getUri())){JSONObject j=new JSONObject(new String(readAll(in),"UTF-8"));name=j.optString("Name",name);version=j.optString("Version","unknown");id=j.optString("UniqueID","");}catch(Exception e){version="manifest unreadable";}}out.append("• ").append(name).append("  ").append(version);if(!id.isEmpty())out.append("\n  ").append(id);out.append("\n");count++;}if(count==0)out.append("No mod folders found.");modsList.setText(out.toString());status.setText("Found "+count+" mod folders.");}catch(Exception e){status.setText("Could not read Mods folder: "+e.getMessage());}}
  private void installZip(Uri uri){if(rootUri==null){status.setText("Grant SMAPI game-folder access before importing a ZIP.");return;}new AlertDialog.Builder(this).setTitle("Install mod ZIP?").setMessage("The ZIP will be extracted into your selected Mods folder. Existing files with matching names may be replaced. Make sure you have a backup.").setNegativeButton("Cancel",null).setPositiveButton("Install",(a,b)->{try{int files=0;DocumentFile dest=modsDirectory();if(dest==null||!dest.isDirectory())throw new IOException("abc.smapi.gameloader/files/Mods folder not found.");try(InputStream raw=getContentResolver().openInputStream(uri);ZipInputStream zip=new ZipInputStream(new BufferedInputStream(raw))){ZipEntry e;byte[] buf=new byte[8192];while((e=zip.getNextEntry())!=null){String path=e.getName().replace('\\','/');if(path.startsWith("/")||path.contains("../")||path.equals("..")||path.startsWith("__MACOSX/")||path.endsWith(".DS_Store"))continue;DocumentFile parent=dest;String[] parts=path.split("/");for(int n=0;n<parts.length-(e.isDirectory()?0:1);n++){if(parts[n].isEmpty())continue;DocumentFile next=parent.findFile(parts[n]);if(next==null)next=parent.createDirectory(parts[n]);if(next==null||!next.isDirectory())throw new IOException("Cannot create folder "+parts[n]);parent=next;}if(!e.isDirectory()){String fn=parts[parts.length-1];if(fn.isEmpty())continue;DocumentFile old=parent.findFile(fn);if(old!=null)old.delete();DocumentFile nf=parent.createFile(mime(fn),fn);if(nf==null)throw new IOException("Cannot create "+fn);try(OutputStream out=getContentResolver().openOutputStream(nf.getUri())){int n;while((n=zip.read(buf))>0)out.write(buf,0,n);}files++;}zip.closeEntry();}}status.setText("ZIP import complete. Extracted "+files+" files.");showMods();}catch(Exception e){status.setText("ZIP install failed: "+e.getMessage());}}).show();}
  private String mime(String n){String l=n.toLowerCase(Locale.ROOT);if(l.endsWith(".json"))return "application/json";if(l.endsWith(".png"))return "image/png";if(l.endsWith(".jpg")||l.endsWith(".jpeg"))return "image/jpeg";if(l.endsWith(".txt"))return "text/plain";return "application/octet-stream";}
  private void analyzeLog(Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){String s=new String(readAll(in),"UTF-8");int errors=0,warnings=0,failed=0;StringBuilder hits=new StringBuilder();for(String line:s.split("\\r?\\n")){String l=line.toLowerCase(Locale.ROOT);if(l.contains("error")){errors++;if(hits.length()<5000)hits.append("ERROR: ").append(line).append("\n");}else if(l.contains("warn")){warnings++;if(hits.length()<5000)hits.append("WARN: ").append(line).append("\n");}if(l.contains("failed")||l.contains("could not load")||l.contains("missing dependency"))failed++;}new AlertDialog.Builder(this).setTitle("SMAPI log report").setMessage("Errors: "+errors+"\nWarnings: "+warnings+"\nPossible load failures: "+failed+"\n\n"+(hits.length()==0?"No obvious errors or warnings found.":hits.toString())).setPositiveButton("OK",null).show();}catch(Exception e){status.setText("Log analysis failed: "+e.getMessage());}}
  private void loadSave(){try(InputStream in=getContentResolver().openInputStream(saveUri)){DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);saveDoc=f.newDocumentBuilder().parse(in);Element p=first(saveDoc.getDocumentElement(),"player");if(p==null)throw new IOException("No player element found. Choose the main save file, not SaveGameInfo.");status.setText("Loaded save: "+value(p,"name")+" • Gold: "+value(p,"money"));}catch(Exception e){saveDoc=null;status.setText("Could not read save: "+e.getMessage());}}
  private Element first(Element parent,String tag){NodeList n=parent.getElementsByTagName(tag);return n.getLength()==0?null:(Element)n.item(0);}
  private String value(Element p,String tag){Element e=first(p,tag);return e==null?"":e.getTextContent().trim();}
  private void editSave(){if(saveDoc==null){status.setText("Open a main Stardew save file first.");return;}Element player=first(saveDoc.getDocumentElement(),"player");LinearLayout form=new LinearLayout(this);form.setOrientation(1);EditText name=field(value(player,"name")),gold=field(value(player,"money")),health=field(value(player,"health")),maxHealth=field(value(player,"maxHealth")),stamina=field(value(player,"stamina")),maxStamina=field(value(player,"maxStamina"));addField(form,"Character name",name);addField(form,"Gold",gold);addField(form,"Health",health);addField(form,"Maximum health",maxHealth);addField(form,"Stamina",stamina);addField(form,"Maximum stamina",maxStamina);ScrollView sv=new ScrollView(this);sv.addView(form);
    new AlertDialog.Builder(this).setTitle("Save editor — core stats").setView(sv).setNegativeButton("Cancel",null).setPositiveButton("Save changes",(d,w)->{try{setValue(player,"name",name.getText().toString());setNumber(player,"money",gold.getText().toString());setNumber(player,"health",health.getText().toString());setNumber(player,"maxHealth",maxHealth.getText().toString());setNumber(player,"stamina",stamina.getText().toString());setNumber(player,"maxStamina",maxStamina.getText().toString());writeSaveWithBackup();}catch(Exception e){status.setText("Save edit failed: "+e.getMessage());}}).show();}
  private EditText field(String s){EditText e=new EditText(this);e.setSingleLine(true);e.setText(s);e.setTextColor(TEXT);e.setHintTextColor(MUTED);return e;}
  private void addField(LinearLayout box,String label,EditText e){box.addView(txt(label,12,MUTED,true));box.addView(e);}
  private void setValue(Element p,String tag,String val){Element e=first(p,tag);if(e==null)throw new IllegalArgumentException("Save field missing: "+tag);e.setTextContent(val);}
  private void setNumber(Element p,String tag,String val){long n=Long.parseLong(val.trim());if(n<0||n>2000000000L)throw new IllegalArgumentException("Invalid value for "+tag);setValue(p,tag,Long.toString(n));}
  private void writeSaveWithBackup()throws Exception{if(rootUri==null)throw new IOException("Grant SMAPI game-folder access first so a backup can be created.");byte[] original;try(InputStream in=getContentResolver().openInputStream(saveUri)){original=readAll(in);}DocumentFile files=appFilesDirectory();if(files==null)throw new IOException("Cannot access abc.smapi.gameloader/files.");DocumentFile folder=files.findFile("BentleyBackups");if(folder==null)folder=files.createDirectory("BentleyBackups");if(folder==null)throw new IOException("Cannot create backup folder.");String stamp=new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());DocumentFile backup=folder.createFile("application/octet-stream","save-backup-"+stamp+".xml");if(backup==null)throw new IOException("Cannot create backup file.");try(OutputStream out=getContentResolver().openOutputStream(backup.getUri())){out.write(original);}Transformer tr=TransformerFactory.newInstance().newTransformer();tr.setOutputProperty(OutputKeys.ENCODING,"UTF-8");tr.setOutputProperty(OutputKeys.INDENT,"yes");try(OutputStream out=getContentResolver().openOutputStream(saveUri,"wt")){tr.transform(new DOMSource(saveDoc),new StreamResult(out));}status.setText("Save updated. Automatic backup created: "+backup.getName());}
  private void backupSave(){if(saveUri==null){status.setText("Open a save file first.");return;}try{if(rootUri==null)throw new IOException("Grant SMAPI game-folder access first.");byte[] bytes;try(InputStream in=getContentResolver().openInputStream(saveUri)){bytes=readAll(in);}DocumentFile files=appFilesDirectory();if(files==null)throw new IOException("Cannot access abc.smapi.gameloader/files.");DocumentFile folder=files.findFile("BentleyBackups");if(folder==null)folder=files.createDirectory("BentleyBackups");String stamp=new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());DocumentFile b=folder.createFile("application/octet-stream","manual-backup-"+stamp+".xml");try(OutputStream out=getContentResolver().openOutputStream(b.getUri())){out.write(bytes);}status.setText("Backup created: "+b.getName());}catch(Exception e){status.setText("Backup failed: "+e.getMessage());}}
  private void restoreBackup(){if(rootUri==null||saveUri==null){status.setText("Grant SMAPI game-folder access and open a save first.");return;}DocumentFile filesDir=appFilesDirectory(),folder=filesDir==null?null:filesDir.findFile("BentleyBackups");if(folder==null){status.setText("No backup folder found.");return;}DocumentFile[] all=folder.listFiles();Arrays.sort(all,(a,b)->Long.compare(b.lastModified(),a.lastModified()));ArrayList<DocumentFile> files=new ArrayList<>();for(DocumentFile f:all)if(f.isFile())files.add(f);if(files.isEmpty()){status.setText("No backups found.");return;}String[] labels=new String[files.size()];for(int i=0;i<files.size();i++)labels[i]=files.get(i).getName();new AlertDialog.Builder(this).setTitle("Choose backup to restore").setItems(labels,(d,which)->new AlertDialog.Builder(this).setTitle("Restore this backup?").setMessage("The currently selected save will be replaced. A current backup will be created first.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(x,y)->{try{backupSave();try(InputStream in=getContentResolver().openInputStream(files.get(which).getUri());OutputStream out=getContentResolver().openOutputStream(saveUri,"wt")){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}loadSave();status.setText("Backup restored.");}catch(Exception e){status.setText("Restore failed: "+e.getMessage());}}).show()).show();}
  private byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);return out.toByteArray();}
}
